<?php $x = order_extras($r); $prod = can('requests.production') || can('requests.quote'); $mgr = can('printers.manage'); $allqc = $x['qc_items'] && !array_diff($x['qc_items'], array_keys(array_filter($x['qc'], fn($q) => $q['done']))); ?>
<div class="card mb"><h3>Documents</h3><p class="mb"><?php if ($r['quote_amount'] !== null): ?><a class="btn alt sm" href="/staff/requests/<?= (int) $r['id'] ?>/quote.pdf">Quotation PDF</a> <?php endif; ?><a class="btn alt sm" href="/staff/requests/<?= (int) $r['id'] ?>/challan.pdf">Delivery challan PDF</a> <a class="btn alt sm" href="/staff/requests/<?= (int) $r['id'] ?>/label">Job label with QR</a> <a class="btn alt sm" href="/staff/calculator?order=<?= (int) $r['id'] ?>">Price calculator</a></p></div>
<div class="card mb"><h3>Print jobs <?php if ($x['job_cost'] > 0): ?><span class="muted" style="font-size:.85rem">cost so far <?= e(money($x['job_cost'])) ?><?= $r['quote_amount'] !== null ? ' &middot; margin ' . e(money((float) $r['quote_amount'] - $x['job_cost'])) : '' ?></span><?php endif; ?></h3>
<?php foreach ($x['jobs'] as $j): ?><div class="comment"><b>#<?= (int) $j['id'] ?></b> <?= e((string) ($j['pname'] ?? 'no printer')) ?> &middot; <?= e((string) ($j['iname'] ?? 'no filament')) ?> &middot; <?= e(ucfirst($j['status'])) ?><?= $j['scheduled_for'] ? ' &middot; planned ' . e(fmt_date($j['scheduled_for'])) : '' ?>
<br><span class="who"><?= $j['status'] === 'failed' && (float) $j['actual_grams'] > 0 ? 'wasted ' . e($j['actual_grams']) . ' g, cost ' . e(money((float) $j['material_cost'])) : '' ?><?= $j['status'] === 'done' ? e($j['actual_hours']) . ' h, ' . e($j['actual_grams']) . ' g, cost ' . e(money((float) $j['material_cost'] + (float) $j['machine_cost'])) : 'est. ' . e((string) $j['est_hours']) . ' h, ' . e((string) $j['est_grams']) . ' g' ?></span>
<?php if ($mgr && in_array($j['status'], ['queued', 'printing'], true)): ?><form method="post" action="/staff/jobs/<?= (int) $j['id'] ?>" class="inline mt"><?= csrf_field() ?><input type="hidden" name="back" value="order"><?php if ($j['status'] === 'queued'): ?><button class="btn sm" name="action" value="start">Start</button> <?php endif; ?><input name="actual_hours" inputmode="decimal" placeholder="hours" value="<?= e((string) $j['est_hours']) ?>" style="width:70px;margin:0" aria-label="Actual hours"> <input name="actual_grams" inputmode="decimal" placeholder="grams" value="<?= e((string) $j['est_grams']) ?>" style="width:80px;margin:0" aria-label="Actual grams"> <button class="btn sm alt" name="action" value="finish">Finish</button> <input name="wasted_grams" inputmode="decimal" placeholder="wasted g" style="width:80px;margin:0" aria-label="Filament wasted on a failed print, grams (optional)" title="Only for Failed: grams of filament wasted (optional)"> <button class="btn sm danger" name="action" value="fail" data-confirm="Mark this job as failed? Any wasted grams you entered are deducted from stock.">Failed</button></form><?php endif; ?></div><?php endforeach; ?>
<?php if (!$x['jobs']): ?><p class="muted">No jobs planned.</p><?php endif; ?>
<?php if ($mgr): ?><form method="post" class="mt"><?= csrf_field() ?><input type="hidden" name="action" value="job_add"><div class="row"><div><label>Printer</label><select name="printer_id"><option value="">any</option><?php foreach ($x['printers'] as $p): ?><option value="<?= (int) $p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></div>
<div><label>Filament</label><select name="item_id"><option value="">not tracked</option><?php foreach ($x['filaments'] as $f): ?><option value="<?= (int) $f['id'] ?>"><?= e($f['name']) ?> (<?= e($f['qty']) ?> <?= e($f['unit']) ?>)</option><?php endforeach; ?></select></div></div>
<div class="row"><div><label>Planned date</label><input type="date" name="scheduled_for"></div><div><label>Est. hours</label><input name="est_hours" inputmode="decimal"></div><div><label>Est. grams</label><input name="est_grams" inputmode="decimal"></div></div>
<button class="btn alt sm">Queue job</button></form><?php endif; ?></div>
<div class="card mb"><h3>Quality check <?= $allqc ? badge('Passed', 'p-ok') : '' ?></h3>
<form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="qc"><?php foreach ($x['qc_items'] as $it): $q = $x['qc'][$it] ?? null; ?><label style="font-weight:400;display:block;margin:0 0 6px"><input type="checkbox" name="qc[]" value="<?= e($it) ?>" style="width:auto;margin:0 6px 0 0" <?= $q && $q['done'] ? 'checked' : '' ?> <?= $prod ? '' : 'disabled' ?>><?= e($it) ?><?= $q && $q['done'] ? ' <span class="muted">(' . e((string) $q['uname']) . ', ' . e(fmt_dt($q['at'])) . ')</span>' : '' ?></label><?php endforeach; ?>
<?php if ($prod): ?><button class="btn alt sm mt">Save quality check</button><?php endif; ?></form></div>
<div class="card mb"><h3>Delivery</h3><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delivery"><div class="row"><div><label>How is it delivered?</label><select name="delivery_method" <?= $prod ? '' : 'disabled' ?>><option value="">- not decided -</option><?= options(DELIVERY_METHODS, (string) ($r['delivery_method'] ?? '')) ?></select></div><div><label>Promised date</label><input type="date" name="due_date" value="<?= e((string) $r['due_date']) ?>" <?= $prod ? '' : 'disabled' ?>></div></div>
<div class="row" data-showif="delivery_method=courier|"><div><label>Courier</label><input name="courier" maxlength="80" value="<?= e((string) $r['courier']) ?>" <?= $prod ? '' : 'disabled' ?>></div><div><label>Tracking number</label><input name="tracking" maxlength="80" value="<?= e((string) $r['tracking']) ?>" <?= $prod ? '' : 'disabled' ?>></div></div>
<?= ($r['delivery_method'] ?? '') === 'pickup' ? '<p class="muted">Customer collects it: set the order to <b>Ready / Dispatched</b> when it is ready at the counter, then <b>Completed</b> once it is handed over.</p>' : '' ?><?= ($r['delivery_method'] ?? '') === 'hand' ? '<p class="muted">Our staff delivers it: set <b>Ready / Dispatched</b> when it leaves, then <b>Completed</b> on handover.</p>' : '' ?>
<?= $r['dispatched_at'] ? '<p class="muted">Dispatched ' . e(fmt_dt($r['dispatched_at'])) . '</p>' : '' ?><?php if ($prod): ?><button class="btn alt sm">Save delivery details</button><?php endif; ?></form></div>
<div class="card mb"><h3>Rework and returns</h3>
<?php foreach ($x['issues'] as $i): ?><div class="comment"><?= badge(ucfirst($i['kind']), $i['kind'] === 'return' ? 'p-warn' : 'p-info') ?> <?= badge($i['status'] === 'open' ? 'Open' : 'Resolved', $i['status'] === 'open' ? 'p-bad' : 'p-ok') ?> <?= e($i['reason']) ?><?= $i['cost'] !== null ? ' &middot; cost ' . e(money($i['cost'])) : '' ?><br><span class="who"><?= e((string) $i['uname']) ?>, <?= e(fmt_dt($i['created_at'])) ?><?= $i['resolution'] ? ' &middot; ' . e($i['resolution']) : '' ?></span>
<?php if ($i['status'] === 'open' && can('requests.create')): ?><form method="post" class="inline mt"><?= csrf_field() ?><input type="hidden" name="action" value="issue_resolve"><input type="hidden" name="issue_id" value="<?= (int) $i['id'] ?>"><input name="resolution" maxlength="500" placeholder="What was done" style="margin:0;width:200px" aria-label="Resolution"> <button class="btn sm alt">Resolve</button></form><?php endif; ?></div><?php endforeach; ?>
<?php if (!$x['issues']): ?><p class="muted">None.</p><?php endif; ?>
<?php if (can('requests.create')): ?><form method="post" class="mt"><?= csrf_field() ?><input type="hidden" name="action" value="issue"><div class="row"><div><label>Type</label><select name="kind"><option value="rework">Rework (reprint, fix)</option><option value="return">Return</option></select></div><div><label>Cost to us (Rs., optional)</label><input name="cost" inputmode="decimal"></div></div><label>Reason</label><input name="reason" maxlength="500" required><button class="btn alt sm">Record</button></form><?php endif; ?></div>
